		v, _ := it0.Next()
		got = append(got, v)
	}
	if !eq(got, []int{1, 2, 4, 8}) {
		t.Fatalf("iterate = %v", got)
	}

	state := 0
	u := core.NewUnfold(0, func(st int) (int, int, bool) {
		if st >= 3 {
			return 0, st, false
		}
		return st, st + 1, true
	})
	_ = state
	if got := collect(u); !eq(got, []int{0, 1, 2}) {
		t.Fatalf("unfold = %v", got)
	}
}

