func TestPeekNth(t *testing.T) {
	a := []int{10, 20, 30}
	p := it.PeekNth(slice(a...))
	for start := 0; start < len(a)+2; start++ {
		for realIdx := start; realIdx < len(a)+2; realIdx++ {
			peekIdx := realIdx - start
			v, ok := p.PeekNth(peekIdx)
			if realIdx < len(a) {
				if !ok || v != a[realIdx] {
					t.Fatalf("peek_nth(%d) at start %d = %v,%v want %d", peekIdx, start, v, ok, a[realIdx])
				}
			} else if ok {
				t.Fatalf("peek_nth(%d) should be out of range", peekIdx)
			}
		}
		v, ok := p.Next()
		if start < len(a) {
			if !ok || v != a[start] {
				t.Fatalf("next at start %d = %v,%v", start, v, ok)
			}
		} else if ok {
			t.Fatalf("next should be done at start %d", start)
		}
	}
}

