type boomErr struct{}

func (boomErr) Error() string { return "boom" }

func TestRepairTail(t *testing.T) {
	v := []int{5, 9, 8, 4, 2, 12, 0}
	if got := it.Tail(slice(v...), 3); !eq(got, []int{2, 12, 0}) {
		t.Fatalf("tail(3) = %v", got)
	}
	if got := it.Tail(slice(v...), 10); !eq(got, v) {
		t.Fatalf("tail(10) = %v", got)
	}
	if got := it.Tail(slice(v...), 1); !eq(got, []int{0}) {
		t.Fatalf("tail(1) = %v", got)
	}
	if got := it.Tail(slice(v...), 0); len(got) != 0 {
		t.Fatalf("tail(0) = %v", got)
	}
}

func TestRepairDropping(t *testing.T) {
	if got := it.Dropping(slice(1, 2, 3, 4), 2); !eq(got, []int{3, 4}) {
		t.Fatalf("dropping = %v", got)
	}
	back := it.DroppingBack(core.FromSlice([]int{0, 3, 6, 9}), 1)
	if got := collect[int](back); !eq(got, []int{0, 3, 6}) {
		t.Fatalf("dropping_back = %v", got)
	}
}

func TestRepairFindOr(t *testing.T) {
	if v, ok := it.FindOrLast(slice(1, 2, 3, 4), func(x int) bool { return x > 5 }); !ok || v != 4 {
		t.Fatalf("find_or_last(>5) = %v, %v", v, ok)
	}
	if v, ok := it.FindOrLast(slice(1, 2, 3, 4), func(x int) bool { return x > 2 }); !ok || v != 3 {
		t.Fatalf("find_or_last(>2) = %v, %v", v, ok)
	}
	if v, ok := it.FindOrLast(slice(1, 2, 3, 4), func(x int) bool { return x > 0 }); !ok || v != 1 {
		t.Fatalf("find_or_last(>0) = %v, %v", v, ok)
	}
	if v, ok := it.FindOrFirst(slice(1, 2, 3, 4), func(x int) bool { return x > 5 }); !ok || v != 1 {
		t.Fatalf("find_or_first(>5) = %v, %v", v, ok)
	}
	if v, ok := it.FindOrFirst(slice(1, 2, 3, 4), func(x int) bool { return x > 2 }); !ok || v != 3 {
		t.Fatalf("find_or_first(>2) = %v, %v", v, ok)
	}
	if _, ok := it.FindOrLast(slice[int](), func(x int) bool { return true }); ok {
		t.Fatal("find_or_last empty should fail")
	}
	if _, ok := it.FindOrFirst(slice[int](), func(x int) bool { return true }); ok {
		t.Fatal("find_or_first empty should fail")
	}
}

func TestRepairPositionTies(t *testing.T) {
	if p, ok := it.PositionMax(slice(1, 1, -1, -1)); !ok || p.First != 1 {
		t.Fatalf("position_max = %+v, %v", p, ok)
	}
	if p, ok := it.PositionMin(slice(1, 1, -1, -1)); !ok || p.First != 2 {
		t.Fatalf("position_min = %+v, %v", p, ok)
	}
}

func TestRepairPositionMinMax(t *testing.T) {
	mn, mx, ok := it.PositionMinMax(slice(1, 1, -1, -1)).IntoOption()
	if !ok || mn != 2 || mx != 1 {
		t.Fatalf("position_minmax = %v %v %v", mn, mx, ok)
	}
	mn, mx, ok = it.PositionMinMax(slice(-3, 0, 1, 5, -10)).IntoOption()
	if !ok || mn != 4 || mx != 3 {
		t.Fatalf("position_minmax2 = %v %v %v", mn, mx, ok)
	}
	r := it.PositionMinMax(slice(10))
	if r.Kind != core.MinMaxOneElement {
		t.Fatalf("position_minmax single kind = %v", r.Kind)
	}
	if _, _, ok := it.PositionMinMax(slice[int]()).IntoOption(); ok {
		t.Fatal("position_minmax empty should have no option")
	}

	abs := func(x int) int {
		if x < 0 {
			return -x
		}
		return x
	}
	mn, mx, ok = it.PositionMinMaxByKey[int, int](slice(1, 1, -1, -1), abs).IntoOption()
	if !ok || mn != 0 || mx != 3 {
		t.Fatalf("position_minmax_by_key = %v %v %v", mn, mx, ok)
	}
	mn, mx, ok = it.PositionMinMaxBy(slice(1, 1, -1, -1), func(a, b int) core.Ordering {
		return core.OrderBy(a, b)
	}).IntoOption()
	if !ok || mn != 2 || mx != 1 {
		t.Fatalf("position_minmax_by = %v %v %v", mn, mx, ok)
	}
}

func TestRepairMinmaxByKey(t *testing.T) {
	in := slice(
		core.Pair[int, string]{First: 1, Second: "a"},
		core.Pair[int, string]{First: 1, Second: "b"},
		core.Pair[int, string]{First: 1, Second: "c"},
	)
	mn, mx, ok := it.MinmaxByKey[core.Pair[int, string], int](in, func(p core.Pair[int, string]) int {
		return p.First
	}).IntoOption()
	if !ok || mn.Second != "a" || mx.Second != "c" {
		t.Fatalf("minmax_by_key = %v %v %v", mn, mx, ok)
	}
}

func TestRepairProcessResultsError(t *testing.T) {
	in := slice(
		core.Pair[int, error]{First: 1},
		core.Pair[int, error]{Second: boomErr{}},
		core.Pair[int, error]{First: 3},
	)
	res, err := free.ProcessResults[int, []int](in, func(src core.Iter[int]) []int { return collect[int](src) })
	if err == nil {
		t.Fatal("process_results did not propagate error")
	}
	if !eq(res, []int{1}) {
		t.Fatalf("process_results result = %v", res)
	}

	ok := slice(core.Pair[int, error]{First: 1}, core.Pair[int, error]{First: 2})
	res2, err2 := free.ProcessResults[int, []int](ok, func(src core.Iter[int]) []int { return collect[int](src) })
	if err2 != nil || !eq(res2, []int{1, 2}) {
		t.Fatalf("process_results ok = %v, %v", res2, err2)
	}
}

func TestRepairInterleaveShortestSizeHint(t *testing.T) {
	a := it.InterleaveShortest(core.RepeatIter(1), core.FromSlice([]int{1, 2, 3}))
	if h := a.SizeHint(); h.Upper != 7 {
		t.Fatalf("unbounded curr hint = %+v", h)
	}
	b := it.InterleaveShortest(core.FromSlice([]int{1, 2, 3}), core.RepeatIter(1))
	if h := b.SizeHint(); h.Upper != 6 {
		t.Fatalf("unbounded next hint = %+v", h)
	}
}

func TestRepairSelectionAndConversion(t *testing.T) {
	nums := []int{6, 9, 1, 14, 0, 4, 8, 7, 11, 2, 10, 3, 13, 12, 5}

	got := it.KSmallestBy[int](slice(nums...), 5, func(a, b int) bool {
		if a%7 != b%7 {
			return a%7 < b%7
		}
		return a < b
	})
	if !eq(got, []int{0, 7, 14, 1, 8}) {
		t.Fatalf("k_smallest_by = %v", got)
	}

	key := func(n int) int { return (n%7)*1000 + n }
	if got := it.KSmallestByKey[int, int](slice(nums...), 5, key); !eq(got, []int{0, 7, 14, 1, 8}) {
		t.Fatalf("k_smallest_by_key = %v", got)
	}
	if got := it.KLargestByKey[int, int](slice(nums...), 5, key); !eq(got, []int{13, 6, 12, 5, 11}) {
		t.Fatalf("k_largest_by_key = %v", got)
	}

	tc := it.TupleCombinations(slice(1, 2, 3, 4), 3)
	var combos [][]int
	for {
		v, ok := tc.Next()
		if !ok {
			break
		}
		combos = append(combos, v)
	}
	want := [][]int{{1, 2, 3}, {1, 2, 4}, {1, 3, 4}, {2, 3, 4}}
	if !reflect.DeepEqual(combos, want) {
		t.Fatalf("tuple_combinations = %v", combos)
	}

	mi := it.MapInto[int, float64](slice(1, 2, 3), func(v int) float64 { return float64(v) })
	if got := collect(mi); !reflect.DeepEqual(got, []float64{1, 2, 3}) {
		t.Fatalf("map_into = %v", got)
	}
}

func TestRepairFilterMapOk(t *testing.T) {
	in := slice(
		core.Pair[int, error]{First: 22},
		core.Pair[int, error]{Second: boomErr{}},
		core.Pair[int, error]{First: 11},
	)
	fm := it.FilterMapOk[int, int](in, func(v int) (int, bool) {
		if v > 20 {
			return v * 2, true
		}
		return 0, false
	})
	var got []core.Pair[int, error]
	for {
		p, ok := fm.Next()
		if !ok {
			break
		}
		got = append(got, p)
	}
	if len(got) != 2 || got[0].Second != nil || got[0].First != 44 {
		t.Fatalf("filter_map_ok = %v", got)
	}
	if got[1].Second == nil {
		t.Fatalf("filter_map_ok lost error: %v", got)
	}
